steps.script:
# THE FIX (report b). The dashed ring must be drawn at the move cap in px and
# NOTHING else: that circle is exactly where _clamp_move_to_budget parks the
# model's centre, so anything added to it is move the drag will not give.
var m = tree.root.get_node("Main")
var mc = m.movement_controller
var ring = m.get_node("BoardRoot/MoveRangeVisual")
var radius: float = ring.get_child(0).points[0].distance_to(mc.drag_start_pos)
var cap_px: float = Measurement.inches_to_px(mc.move_cap_inches)
var extent: float = Measurement.base_extent_px(mc.selected_model)
m.set_meta("ring_probe", "ring_radius=%.1f cap_px=%.1f base_extent=%.1f overdraw=%.2f\"" % [radius, cap_px, extent, (radius - cap_px) / Measurement.PX_PER_INCH])
return abs(radius - cap_px)

# Regression guard the other way round: between v1.17.2 and the Battlewagon
# report this ring was drawn a whole base extent (~79px here, 162px on a
# Battlewagon) beyond the move cap. That overdraw must be zero.
var mc = tree.root.get_node("Main").movement_controller
var ring = tree.root.get_node("Main").get_node("BoardRoot/MoveRangeVisual")
var radius: float = ring.get_child(0).points[0].distance_to(mc.drag_start_pos)
return radius - Measurement.inches_to_px(mc.move_cap_inches)

# The model's CENTRE sits ON the dashed ring at max range: ring == drag limit.
var m = tree.root.get_node("Main")
var mc = m.movement_controller
var ring = m.get_node("BoardRoot/MoveRangeVisual")
var radius: float = ring.get_child(0).points[0].distance_to(mc.drag_start_pos)
var moved: float = mc.current_path[1].distance_to(mc.drag_start_pos)
m.set_meta("ghost_probe", "ghost_on_ring_gap=%.2fpx" % (radius - moved))
return abs(radius - moved)

# Report (a) is still covered, by the HALO rather than the ring: the furthest
# point of the model's base at this max-range position sits on the faint
# MoveHullReach circle, so a wide base never trails off into empty board.
var m = tree.root.get_node("Main")
var mc = m.movement_controller
var ring = m.get_node("BoardRoot/MoveRangeVisual")
var halo = ring.get_node_or_null("MoveHullReach")
if halo == null:
	return 9999.0
var halo_r: float = halo.points[0].distance_to(mc.drag_start_pos)
var moved: float = mc.current_path[1].distance_to(mc.drag_start_pos)
var extent: float = Measurement.base_extent_px(mc.selected_model)
m.set_meta("halo_probe", "halo_radius=%.1f cap_px=%.1f extent=%.1f base_edge_vs_halo=%.2fpx" % [halo_r, Measurement.inches_to_px(mc.move_cap_inches), extent, (moved + extent) - halo_r])
return abs((moved + extent) - halo_r)

# ...and the halo must stay visibly subordinate to the ring, or it becomes a
# second boundary and we are back to the Battlewagon report.
var ring = tree.root.get_node("Main").get_node("BoardRoot/MoveRangeVisual")
var halo = ring.get_node_or_null("MoveHullReach")
if halo == null:
	return "no MoveHullReach halo drawn"
var dash = ring.get_child(0)
if halo.width >= dash.width:
	return "halo stroke %.1f not thinner than ring %.1f" % [halo.width, dash.width]
if halo.default_color.a >= dash.default_color.a:
	return "halo alpha %.2f not fainter than ring %.2f" % [halo.default_color.a, dash.default_color.a]
return "ok"
